import{_ as t,o as a,c as s,a0 as r}from"./chunks/framework.D4fUSYzX.js";const f=JSON.parse('{"title":"ADR 0078: The rework prompt fills the gates fact when the review passed","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0078-the-rework-prompt-fills-the-gates-fact-when-the-review-passed.md","filePath":"adr/0078-the-rework-prompt-fills-the-gates-fact-when-the-review-passed.md"}'),o={name:"adr/0078-the-rework-prompt-fills-the-gates-fact-when-the-review-passed.md"};function h(n,e,i,d,c,l){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0078-the-rework-prompt-fills-the-gates-fact-when-the-review-passed" tabindex="-1">ADR 0078: The rework prompt fills the gates fact when the review passed <a class="header-anchor" href="#adr-0078-the-rework-prompt-fills-the-gates-fact-when-the-review-passed" aria-label="Permalink to &quot;ADR 0078: The rework prompt fills the gates fact when the review passed&quot;">​</a></h1><p>Status: accepted Date: 2026-10-01</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The <code>needs-work</code> state offers the rework task type, and a pull request reaches it by two paths. The review posts a score below the workflow&#39;s score threshold, and the review&#39;s feedback names the work. Or the review passes, the merge position asks the plane action, the action blocks on a merge conflict or a failing CI check, and the merge transition&#39;s <code>pull-request-open</code> branch writes <code>needs-work</code> back (ADR 0068, ADR 0077).</p><p>The <code>{review-verdict}</code> fill of the rework prompt (ADR 0074) takes the newest post that carries the fixed score line, on both paths. On the blocked-merge path that post is the verdict the review already passed. The fill hands the agent a passing score, the agent finds no required changes in it, and the agent starts the turn without the fact that stands on the pull request: the failure is in the gates, not in the review.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>The fill decides the pass with the judgment&#39;s own rule.</strong> The handoff reads the workflow&#39;s score threshold from the config at the prompt render: the <code>score-threshold</code> of the first task type whose transition tests a score judgment, <code>undefined</code> when no transition tests a score. When the standing verdict carries a score that stands at or above that threshold - the <code>&gt;=</code> the <code>score-above-threshold</code> judgment tests - the placeholder fills the gates fact instead of the verdict&#39;s body: the review passed with the score, the failure stands in the pull request&#39;s gates as a merge conflict or a failing CI check, and the agent rebases the branch onto its base and fixes what the gates report.</p><p><strong>Every other read keeps the fill it stood under before the threshold joined it.</strong> A score below the threshold fills the verdict&#39;s body under its header, the way ADR 0074 states. A verdict with no score line, a read that finds no verdict, a read that fails, and a config with no threshold all keep their existing fills, so a template that references the placeholder behaves as before on every config that names no threshold.</p><p>The read itself does not move: the same two timelines, the same newest score-carrying-record rule, the same per-timeline fail-open. The fill decides on the record the judgment would have decided on, one settle earlier.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The rework turn after a blocked merge starts on the right failure: the agent rebases the branch and works the gates, and it does not spend the turn correcting what the review already passed.</li><li>The threshold stands on the config, so an operator&#39;s threshold edit reaches the next rework prompt with no migration: the judgment and the fill decide against the same number.</li><li>A pull request a human labels <code>needs-work</code> by hand, with a passing score, takes the gates fact too: the plane cannot separate the blocked merge from the human&#39;s label, and the gates text sends the agent to check the gates either way.</li><li>The <code>{review-verdict}</code> placeholder keeps one rule across both paths, and a config without a score-testing transition renders every rework prompt as it did before.</li></ul>',11)])])}const w=t(o,[["render",h]]);export{f as __pageData,w as default};
